          "5.2 Accountable, Responsive and Legitimate Government: Transparency, Free and Fair Elections, Open Public Debate, RTI and Legitimacy as People's Own Government",
          "5.3 Economic Growth and Development: Comparison of Economic Growth Rates in Democracies vs Dictatorships (1950-2000) and Other Determining Factors",
          "5.4 Reduction of Inequality and Poverty: The Unjust Distribution of Wealth, Disproportionate Share of Ultra-Rich, High Proportion of Poor and Democratic Lapses",
          "5.5 Accommodation of Social Diversity: Democracy Must Not Simply be Majority Rule, Majority Must Work with Minority, Representation of Diverse Ethnic/Religious Groups",
          "5.6 Dignity and Freedom of the Citizens: Passion for Respect and Freedom, Struggle for Women's Dignity and Equal Status, Caste Injustices Redressal, Democracy's Continuous Examination"
