          "2.2 Comparing the Three Sectors: Value of Final Goods and Services, Gross Domestic Product (GDP) Calculation and Central Statistics Office (CSO)",
          "2.3 Historical Changes in Sectors: Primary to Secondary to Tertiary Dominance in Developed Nations",
          "2.4 Rising Importance of the Tertiary Sector in India: Basic Services, Agriculture/Industry Development, Rise in Income Levels, Information Technology Services",
          "2.5 Where are Most People Employed? Discrepancy Between Share in GDP and Employment Share (Primary Sector Employing Half the Workforce)",
          "2.6 Underemployment and Disguised Unemployment in Agriculture and Informal Services",
          "2.7 How to Create More Employment? Agricultural Infrastructure (Dams, Canals, Cold Storage), Credit Facilities, Promoting Rural Industries (Dal Mills, Honey Collection), Tourism and MGNREGA 2005 (100 Days Guaranteed Wage Employment)",
          "2.8 Division of Sectors as Organised and Unorganised: Working Conditions, Job Security, Overtime, Paid Leave, Social Security Benefits",
          "2.9 How to Protect Workers in the Unorganised Sector? Vulnerable Groups in Rural (Landless Labourers, Small/Marginal Farmers, Artisans) and Urban Areas (Daily Wage Earners, Street Vendors, Ragpickers)",
          "2.10 Sectors in Terms of Ownership: Public Sector (Government Owned, Service Motive) vs Private Sector (Individually Owned, Profit Motive) and Government Responsibilities"
