          "3.1 Money as a Medium of Exchange: Double Coincidence of Wants and Elimination by Money",
          "3.2 Modern Forms of Money: Currency (Paper Notes and Coins, Authorisation by Reserve Bank of India on Behalf of Central Government) and Deposits with Banks (Demand Deposits, Cheque Payments)",
          "3.3 Loan Activities of Banks: Intermediary Role Between Depositors and Borrowers, Credit Spread / Net Interest Margin",
          "3.4 Two Different Credit Situations: Credit as an Asset (Salim the Shoe Manufacturer) vs Credit as a Debt-Trap (Swapna the Groundnut Farmer)",
          "3.5 Terms of Credit: Interest Rate, Collateral / Security, Documentation Requirement and Mode of Repayment",
          "3.6 Formal Sector Credit in India: Commercial Banks, Cooperative Societies vs Informal Sector Credit: Moneylenders, Traders, Employers, Relatives (High Interest Rates, Exploitation)",
          "3.7 Role of Reserve Bank of India (RBI) in Supervising Formal Sector Credit (CRR, SLR, Priority Sector Lending)",
          "3.8 Cheap and Affordable Credit is Crucial for the Country's Development (Need to Expand Formal Sector)",
          "3.9 Self-Help Groups (SHGs) for the Poor: Composition, Functioning, Collateral-Free Loans, Overcoming Rural Moneylenders and Empowering Rural Women (Grameen Bank of Bangladesh Model)"
