        "16.6 Mechanism of Concentration of the Filtrate: Counter-Current Mechanism in Henle's Loop and Vasa Recta (Role of NaCl and Urea in Medullary Interstitium)",
        "16.7 Regulation of Kidney Function: Hypothalamus (Osmoreceptors, ADH / Vasopressin), Juxtaglomerular Apparatus (JGA, Renin-Angiotensin-Aldosterone System - RAAS) and Atrial Natriuretic Factor (ANF)",
        "16.8 Micturition (Neural Reflex, Urine Composition) and Role of other Organs in Excretion (Lungs, Liver, Skin / Sweat and Sebaceous Glands)",
        "16.9 Disorders of the Excretory System: Uremia, Hemodialysis (Artificial Kidney), Renal Failure, Kidney Transplantation, Renal Calculi (Kidney Stones) and Glomerulonephritis"
