        "19.3 Pituitary Gland (Hypophysis): Adenohypophysis / Anterior Pituitary (GH - Dwarfism, Gigantism, Acromegaly; PRL, TSH, ACTH, LH, FSH) and Neurohypophysis / Posterior Pituitary (Oxytocin and Vasopressin / ADH)",
        "19.4 Pineal Gland (Melatonin - 24-Hour Diurnal Rhythm, Sleep-Wake Cycle, Body Temperature)",
